interface ConfiguracaoApp {
  nomeServico: string;
  portas: number[];
}

function criarConfiguracaoPadrao(): ConfiguracaoApp {
  return { nomeServico: "api", portas: [3000, 3001] };
}

// Reexportar um tipo exige "export type" com isolatedModules ligado: uma
// ferramenta que só vê este ficheiro não sabe que ConfiguracaoApp desaparece
// em tempo de execução, a não ser que a sintaxe o diga de forma explícita.
export type { ConfiguracaoApp };
export { criarConfiguracaoPadrao };

export interface OpcoesFormatacao {
  casasDecimais?: number;
  simboloMoeda?: string;
}

export function formatarPreco(valor: number, opcoes: OpcoesFormatacao = {}): string {
  const casas = opcoes.casasDecimais ?? 2;
  const simbolo = opcoes.simboloMoeda ?? "EUR";
  return valor.toFixed(casas) + " " + simbolo;
}

console.log(formatarPreco(19.9));
console.log(formatarPreco(19.9, { casasDecimais: 0, simboloMoeda: "USD" }));
// 19.90 EUR
// 20 USD

