type EtapaPipeline = "desenvolvimento" | "verificacaoDeTipos" | "bundleFinal";

function ferramentaRecomendada(etapa: EtapaPipeline): string {
  switch (etapa) {
    case "desenvolvimento":
      return "tsx ou ts-node (correr .ts diretamente, sem build manual)";
    case "verificacaoDeTipos":
      return "tsc --noEmit (so verifica tipos, nao gera JavaScript)";
    case "bundleFinal":
      return "um bundler como esbuild ou vite (rapido, sem verificar tipos)";
    default: {
      const _exaustivo: never = etapa;
      return _exaustivo;
    }
  }
}

console.log(ferramentaRecomendada("desenvolvimento"));
console.log(ferramentaRecomendada("verificacaoDeTipos"));
console.log(ferramentaRecomendada("bundleFinal"));
