interface RespostaApi {
  estado: number;
  corpo: string;
}

function interpretar(resposta: RespostaApi): string {
  return resposta.estado + ": " + resposta.corpo;
}

console.log(interpretar({ estado: 200, corpo: "ok" }));
// 200: ok

export type { RespostaApi };
export { interpretar };

export interface OpcoesData {
  comHora?: boolean;
}

export function formatarData(data: Date, opcoes: OpcoesData = {}): string {
  const base = data.toISOString().slice(0, 10);
  return opcoes.comHora ? base + " " + data.toISOString().slice(11, 16) : base;
}

const dataFixa = new Date(Date.UTC(2026, 0, 15, 9, 30));
console.log(formatarData(dataFixa));
console.log(formatarData(dataFixa, { comHora: true }));
// 2026-01-15
// 2026-01-15 09:30

interface Sucesso<T> {
  sucesso: true;
  valor: T;
}

interface Falha {
  sucesso: false;
  erro: string;
}

type Resultado<T> = Sucesso<T> | Falha;

function envolver<T>(valor: T): Resultado<T> {
  return { sucesso: true, valor };
}

function falhar(erro: string): Resultado<never> {
  return { sucesso: false, erro };
}

function descrever<T>(resultado: Resultado<T>): string {
  if (resultado.sucesso) {
    return "sucesso: " + JSON.stringify(resultado.valor);
  }
  return "falha: " + resultado.erro;
}

console.log(descrever(envolver(42)));
console.log(descrever(falhar("tempo esgotado")));
// sucesso: 42
// falha: tempo esgotado

export type { Resultado };
export { envolver, falhar, descrever };
